#!/usr/bin/env node
// Removes the Example control, its tests and all references generated by yo easy-ui5.
// Usage: node remove-example.mjs [--dry-run]
// Idempotent: running it again after a successful run changes nothing.

import { existsSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const root = dirname(fileURLToPath(import.meta.url));
const dryRun = process.argv.includes("--dry-run");

const filesToDelete = [
	"src/Example.ts",
	"src/ExampleRenderer.ts",
	"src/themes/base/Example.less",
	"test/Example.html",
	"test/Example.ts",
	"test/qunit/Example.qunit.ts"
];

// [file, description, replacer]
const edits = [
	[
		"src/library.ts",
		"remove ExampleColor enum and Example registrations",
		(s) =>
			s
				.replace(/types: \["miyasuta\.library\.ExampleColor"\]/, "types: []")
				.replace(/controls: \["miyasuta\.library\.Example"\]/, "controls: []")
				.replace(/\/\*\*\s*\n \* Semantic Colors[\s\S]*?thisLib\.ExampleColor = ExampleColor;[^\n]*\n/, "")
	],
	[
		"src/themes/base/library.source.less",
		"remove Example.less import",
		(s) => s.replace(/\n*@import "Example\.less";\s*\n?/, "\n")
	],
	[
		"test/qunit/testsuite.qunit.ts",
		"remove Example test entry",
		(s) => s.replace(/tests:\s*\{[\s\S]*?\n\t\}\n/, "tests: {}\n")
	],
	[
		"package.json",
		"make start script independent of Example.html",
		(s) => s.replace(/ui5 serve -o test-resources\/miyasuta\/library\/Example\.html/, "ui5 serve")
	]
];

const log = (msg) => console.log(`${dryRun ? "[dry-run] " : ""}${msg}`);

for (const rel of filesToDelete) {
	const path = join(root, rel);
	if (!existsSync(path)) continue;
	log(`delete ${rel}`);
	if (!dryRun) rmSync(path);
}

for (const [rel, description, replacer] of edits) {
	const path = join(root, rel);
	if (!existsSync(path)) continue;
	const before = readFileSync(path, "utf8");
	const after = replacer(before);
	if (before === after) continue;
	log(`edit   ${rel} (${description})`);
	if (!dryRun) writeFileSync(path, after);
}

log("done");
